INSERT INTO quizzes (book_id, chapter, kind, title) VALUES (19, 22, 'theory', 'Квиз: файлы, права, атомарная запись');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (19, 22, 0, 'Почему временный файл для атомарной замены создают в том же каталоге, что и цель?', '["Чтобы не вызывать fsync", "Чтобы имя файла получилось короче", "Чтобы rename не пересёк границу файловой системы и не упал с EXDEV", "Чтобы маска umask не применялась"]', 2, 'Переименование атомарно только внутри одной файловой системы; между разными оно даёт EXDEV. Каталог цели гарантированно на той же файловой системе, что и сама цель.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (19, 22, 1, 'Что вернёт Path(''/srv/app'') / ''/etc/passwd''?', '["PosixPath(''/etc/passwd'')", "PosixPath(''/srv/app/etc/passwd'')", "PosixPath(''/srv/app//etc/passwd'')", "Будет ValueError"]', 0, 'Абсолютный правый операнд отбрасывает левую часть. Поэтому «база / ввод пользователя» нельзя считать безопасным без проверки результата.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (19, 22, 2, 'Маска umask равна 022. Файл создают через os.open с режимом 0o666. Какой режим он получит?', '["0o666", "0o622", "0o755", "0o644"]', 3, 'Режим при создании равен запрошенный & ~umask: 0o666 & ~0o022 = 0o644. Позже chmod маске не подчиняется.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (19, 22, 3, 'Чем flock надёжнее лок-файла с O_EXCL и PID при аварийном завершении процесса?', '["Он без исключений работает на любой сетевой файловой системе", "Ядро снимает блокировку со смертью процесса, устаревшей блокировки не остаётся", "Он запрещает остальным программам открывать файл", "Он сам записывает PID владельца"]', 1, 'Блокировка принадлежит открытому файловому описанию и исчезает, когда закрыты все дескрипторы, в том числе при смерти процесса. Но она рекомендательная: другие программы могут просто писать в файл.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (19, 22, 4, 'Почему в проверке выхода из каталога resolve() вызывают раньше is_relative_to()?', '["is_relative_to() работает только с существующими файлами", "resolve() проверяет права доступа к файлу", "is_relative_to() сравнивает только текст и не идёт ни по ссылкам, ни по «..»", "resolve() делает путь короче"]', 2, 'Метод is_relative_to() чисто строковый. Только resolve() идёт по символическим ссылкам и убирает «..», после чего сравнение с разрешённой базой имеет смысл.');
